export function normalizePath(path: string) {
  return path.replace(/^\/+|\/+$/g, '');
}

export function pathFor(page: SitePage, locale: Locale) {
  const path = locale === 'fr' ? page.frPath : page.path;
  return path ? `/${path}` : '/';
}

export function publicPathFor(page: SitePage, locale: Locale) {
  return pathFor(page, locale);
}

export function getPageByPath(path: string, locale: Locale, includeDrafts = false) {
  const normalized = normalizePath(path);
  const page = pageRegistry.find((entry) => normalizePath(locale === 'fr' ? entry.frPath : entry.path) === normalized);
  if (!page || (!includeDrafts && !page.published)) return undefined;
  return page;
}

export function getPageByKey(key: string) {
  return pageRegistry.find((page) => page.key === key);
}

export function getPublishedPages(locale: Locale) {
  return pageRegistry.filter((page) => page.published && (locale === 'en' ? page.path : page.frPath));
}

export function getHomePath() {
  return '/';
}
